def _warmup():
    ew._warmup()
    nw = 4; L = nw+2*X; z = np.zeros(L)
    _value_ext(np.zeros(nw), 0, nw-1, X, nw, z, np.empty(L), np.empty(L), np.empty(L), np.empty(L))
    _dp_step(nw, *[np.zeros(L) for _ in range(11)], 1.0, 1.0, np.empty(nw), np.empty(nw, np.uint16))

